runtime.content:
// core/runtime/machine-runtime.js
// The shared, framework-NEUTRAL FSM runtime (behavior-layer-design.md §6.2 risk #1).
// Dependency-free: ZERO imports, ZERO framework code. It drives ANY machine shaped
// { initial, context, states } through a pure transition() fn (see machine.js). Every
// per-framework connector (connect.react/vanilla/angular) layers its own reactivity on
// top of this one interpreter, so React/Bootstrap/Angular never diverge — one source.
//
// Interface (the "useMachineRuntime/send" shape referenced by §5.1):
//   const rt = createMachineRuntime(machine, transition, config)
//   rt.state            -> current state name ("closed" | "open" | "animatingOut" | ...)
//   rt.context          -> merged context (machine defaults <- per-instance config)
//   rt.send(event)      -> apply an event; returns a snapshot {state, context, actions}
//   rt.can(eventType)   -> is `eventType` accepted in the current state?
//   rt.matches(state)   -> is the runtime in `state`?
//   rt.subscribe(fn)    -> observe snapshots (fires immediately, returns unsubscribe)
//   rt.snapshot()       -> {state, context, actions}
//
// `actions` carries the declarative entry/exit action NAMES the machine declared for the
// transition (e.g. "trapFocus"). The runtime is intentionally side-effect-free: it does
// NOT execute them — each connector decides how (focus trap, scroll lock, ...) for its DOM.

export function createMachineRuntime(machine, transition, config = {}) {
  let state = machine.initial;
  let context = { ...(machine.context || {}), ...(config || {}) };
  const listeners = new Set();
  let lastActions = { entry: [], exit: [] };

  const snapshot = () => ({ state, context: { ...context }, actions: { ...lastActions } });
  const notify = () => { for (const fn of listeners) fn(snapshot()); };

  function send(event) {
    const evt = typeof event === "string" ? { type: event } : (event || {});
    const result = transition(state, evt, context) || { state, changed: false };
    lastActions = { entry: result.entry || [], exit: result.exit || [] };
    if (result.changed) {
      state = result.state;
      notify();
    }
    return snapshot();
  }

  const can = (eventType) => {
    const node = machine.states[state];
    return !!(node && node.on && node.on[eventType]);
  };
  const matches = (s) => state === s;

  function subscribe(fn) {
    listeners.add(fn);
    fn(snapshot());
    return () => listeners.delete(fn);
  }

  return {
    get state() { return state; },
    get context() { return context; },
    send, can, matches, subscribe, snapshot,
  };
}

// Alias: connectors that read the runtime as a hook-style factory import this name.
export const useMachineRuntime = createMachineRuntime;

machine.content:
// company/behaviors/dialog/machine.patch.js
// The COMPANY brand extension of the core dialog FSM (behavior-layer-design.md §3.2 / §5.2).
//
// PURELY ADDITIVE (monotonic). This patch is *merged* onto the core dialogMachine by the
// resolver's applyPatch() (§4.2) — it may ONLY add states / events / context keys. It must
// NOT delete, move, or rebind any core state (closed / open / animatingOut) or any existing
// core transition. The determinism gate (recipe action a7) asserts exactly that.
//
// This file never imports core/behaviors/dialog/machine.js and never mutates it on disk —
// core is read-only to the company bucket. The merge happens at fetch/compose time only.
//
// Patch grammar (consumed by applyPatch, §4.2):
//   context:     { ...newKeys }   — added to core context (additive; no core key removed)
//   addStates:   { <name>: node } — brand-new states only (name must NOT already exist in core)
//   amendStates: { <state>: { on: { <EVENT>: target } } }
//                                  — ADD new events to an existing core state's `on` map.
//                                    May only introduce NEW event keys; rebinding an existing
//                                    core event is a hard error in applyPatch (monotonic rule).

export const patch = {
  // New config key — brand chrome toggle (additive; core context keys untouched).
  context: { brandHeader: true },

  // Brand-new state: the dialog can be MINIMIZED. RESTORE returns to open; CLOSE
  // dismisses it. CLOSE targets the core `closed` state directly — matching the
  // core fix (defect 1) that removed the dead `animatingOut` leg. Focus/scroll
  // cleanup still runs via the connector's React effects keyed on `isOpen`.
  addStates: {
    minimized: {
      on: { RESTORE: "open", CLOSE: "closed" },
    },
  },

  // Amend the existing core `open` state by ADDING a MINIMIZE event (new event key only).
  // Core's `open` already owns CLOSE → animatingOut; that binding is left exactly as-is.
  amendStates: {
    open: {
      on: { MINIMIZE: "minimized" },
    },
  },
};

export default patch;

connect.content:
// core/behaviors/dialog/connect.react.tsx
// CONNECTOR MODULE — React variant (framework axis).
// behavior-layer-design.md §1.3 & §5.1.
//
// THIN by design: it owns NO behavior. It imports the framework-NEUTRAL dialog
// machine + pure transition() from ./machine.js and drives them through the shared
// core/runtime/machine-runtime.js (the `useMachineRuntime`/`send` interface). React is
// the ONLY thing this file adds — reactivity (useSyncExternalStore) + the React
// `normalizeProps` mapping (part/data-state/role/aria + onClick/className/style) + the
// React DOM realisation of the machine's declarative action names (trapFocus /
// releaseFocus / lockScrollIfModal / unlockScroll) and a body-portal so the modal is
// viewport-relative rather than anchored inside an app card.
//
// It does NOT import any CSS or token file: design stays orthogonal and meets behavior
// only at the markup contract (parts.md). The prop-getters emit `part="…"` /
// `data-state="…"` exactly so `core/design/dialog.css` can style them with zero coupling.

import * as React from "react";
import { createPortal } from "react-dom";
import { dialogMachine, transition } from "./machine.js";
import { createMachineRuntime } from "../../runtime/machine-runtime.js";

// ---- Config / api surface (the cross-framework shape; identical in vanilla/angular) ----

export interface DialogConfig {
  scrollable?: boolean; // scroll / no-scroll variant
  resizable?: boolean; // resizable + dimensions opt-in
  width?: string | null;
  height?: string | null;
}

export type DialogState = "closed" | "open";

export interface DialogApi {
  state: DialogState;
  isOpen: boolean;
  open: () => void;
  close: () => void;
  // The dialog surface ref — exposed so a focus trap can query the focusables inside
  // [part="content"]. Already wired into getContentProps()'s returned `ref`.
  contentRef: React.RefObject<HTMLElement>;
  // Prop-getters — Zag/Ark-shaped (research §2): emit the parts.md contract attributes.
  getOverlayProps: () => React.HTMLAttributes<HTMLElement> & Record<string, unknown>;
  getContentProps: () => React.HTMLAttributes<HTMLElement> & Record<string, unknown>;
  // The single scroll region. Reflects ctx.scrollable onto [data-scroll] so the CSS
  // (core/design/dialog.css) drives overflow on [part="body"] alone (scroll/no-scroll
  // is functional + the header stays pinned outside it).
  getBodyProps: () => React.HTMLAttributes<HTMLElement> & Record<string, unknown>;
  getTitleProps: () => React.HTMLAttributes<HTMLElement> & Record<string, unknown>;
  getCloseProps: () => React.ButtonHTMLAttributes<HTMLButtonElement> & Record<string, unknown>;
}

// ---- React normalizeProps ----
// Per-framework seam (§1.3): React already speaks onClick/className/style, so the mapping
// is mostly identity, but we centralize it here so the prop-getters stay framework-neutral
// in spirit and the only React-specific knowledge lives in one spot.
type PropBag = Record<string, unknown>;
function normalizeProps<T extends PropBag>(props: T): T {
  const out: PropBag = {};
  for (const [k, v] of Object.entries(props)) {
    if (v === undefined) continue; // drop empty style/handlers so React doesn't warn
    out[k] = v;
  }
  return out as T;
}

// ---- Portal (the root-cause modal fix) -------------------------------------------
// Renders children into document.body so the overlay's `position: fixed` is anchored to
// the VIEWPORT, not to a transformed/positioned app Card ancestor (which made the prior
// build render as an inline card). SSR-safe: it no-ops when there is no document. Both
// the core demo and the company connector (a3) mount their overlay+content through this.
export function DialogPortal({
  children,
  container,
}: {
  children: React.ReactNode;
  container?: Element | null;
}): React.ReactPortal | null {
  if (typeof document === "undefined") return null;
  return createPortal(children, container ?? document.body);
}

// ---- Focus management helpers ----------------------------------------------------
// Tabbable-element selector used to find the first focusable (on open) and to cycle Tab.
const FOCUSABLE_SELECTOR = [
  "a[href]",
  "area[href]",
  "button:not([disabled])",
  'input:not([disabled]):not([type="hidden"])',
  "select:not([disabled])",
  "textarea:not([disabled])",
  "audio[controls]",
  "video[controls]",
  "details > summary:first-of-type",
  '[contenteditable]:not([contenteditable="false"])',
  '[tabindex]:not([tabindex="-1"])',
].join(",");

function getFocusable(container: HTMLElement | null): HTMLElement[] {
  if (!container || typeof container.querySelectorAll !== "function") return [];
  return Array.from(container.querySelectorAll(FOCUSABLE_SELECTOR)).filter(
    (el): el is HTMLElement =>
      el instanceof HTMLElement &&
      !el.hasAttribute("disabled") &&
      el.getAttribute("aria-hidden") !== "true" &&
      // visible (skips display:none); content itself is visible whenever open
      (el.offsetWidth > 0 || el.offsetHeight > 0 || el.getClientRects().length > 0),
  );
}

// ---- Reusable DOM-concern hook (trapFocus / releaseFocus / ESC / scroll lock) -----
// The machine NAMES these actions declaratively; the runtime is side-effect-free, so the
// connector realises them for its DOM. This hook is the single implementation, exported
// so the company connector (a3) imports it instead of duplicating the focus logic (DRY).
//
//   contentRef — ref to the [part="content"] element (focusables live here)
//   isOpen     — true while the machine is in the `open` state
//   onClose    — invoked on Escape; dispatches the machine's CLOSE event
//   options    — { modal } : when modal (default), lock body scroll while open
export function useDialogDom(
  contentRef: React.RefObject<HTMLElement>,
  isOpen: boolean,
  onClose: () => void,
  { modal = true }: { modal?: boolean } = {},
): void {
  // Element focused before opening, restored on close (releaseFocus).
  const triggerRef = React.useRef<HTMLElement | null>(null);

  // trapFocus + releaseFocus + ESC — listener mounted only while open.
  React.useEffect(() => {
    if (!isOpen) return undefined;
    if (typeof document === "undefined") return undefined;

    const content = contentRef.current;

    // Record the trigger (whatever held focus when the dialog opened) BEFORE we move it.
    triggerRef.current =
      document.activeElement instanceof HTMLElement ? document.activeElement : null;

    // Move focus into the dialog: first focusable, else the content itself (give it a
    // programmatic tabindex so the surface can receive focus as a fallback).
    const initial = getFocusable(content);
    if (initial.length > 0) {
      initial[0].focus();
    } else if (content) {
      if (!content.hasAttribute("tabindex")) content.setAttribute("tabindex", "-1");
      content.focus();
    }

    function onKeyDown(e: KeyboardEvent) {
      if (e.key === "Escape") {
        e.stopPropagation();
        onClose();
        return;
      }
      if (e.key !== "Tab") return;

      const node = contentRef.current;
      const focusables = getFocusable(node);
      const active = document.activeElement as HTMLElement | null;

      // No focusables (or focus escaped the dialog) → pin focus to the content surface.
      if (focusables.length === 0) {
        e.preventDefault();
        node?.focus();
        return;
      }

      const first = focusables[0];
      const last = focusables[focusables.length - 1];
      const inside = !!(node && active && node.contains(active));

      if (e.shiftKey) {
        if (active === first || !inside) {
          e.preventDefault();
          last.focus();
        }
      } else if (active === last || !inside) {
        e.preventDefault();
        first.focus();
      }
    }

    // Capture phase so the trap wins before app-level handlers.
    document.addEventListener("keydown", onKeyDown, true);

    return () => {
      document.removeEventListener("keydown", onKeyDown, true);
      // releaseFocus: return focus to the trigger that opened the dialog.
      const trigger = triggerRef.current;
      if (trigger && typeof trigger.focus === "function") trigger.focus();
    };
  }, [isOpen, contentRef, onClose]);

  // lockScrollIfModal / unlockScroll — hide body overflow while a modal is open.
  React.useEffect(() => {
    if (!isOpen || !modal) return undefined;
    if (typeof document === "undefined") return undefined;

    const body = document.body;
    const prevOverflow = body.style.overflow;
    body.style.overflow = "hidden";
    return () => {
      body.style.overflow = prevOverflow;
    };
  }, [isOpen, modal]);
}

// One title id per hook instance so `content[aria-labelledby]` → `title[id]` (a11y baseline).
let __dialogTitleSeq = 0;

/**
 * useDialog(config) — the React hook. Returns the api: { state, isOpen, open, close,
 * contentRef } plus the prop-getters. The machine + transition are the single source of
 * truth; this hook subscribes React to runtime snapshots, projects them onto React-shaped
 * props, and realises the machine's declarative DOM actions via useDialogDom + DialogPortal.
 */
export function useDialog(config: DialogConfig = {}): DialogApi {
  // The runtime is created ONCE per mounted hook (stable identity across renders). It merges
  // machine defaults <- per-instance config exactly like the neutral runtime documents.
  const runtimeRef = React.useRef<ReturnType<typeof createMachineRuntime> | null>(null);
  if (runtimeRef.current === null) {
    runtimeRef.current = createMachineRuntime(dialogMachine, transition, config);
  }
  const rt = runtimeRef.current;

  const titleId = React.useMemo(() => `dialog-title-${++__dialogTitleSeq}`, []);

  // Bridge the neutral subscribe/snapshot interface into React's external-store contract.
  const subscribe = React.useCallback(
    (onChange: () => void) => rt.subscribe(() => onChange()),
    [rt],
  );
  // getSnapshot must return a stable value when nothing changed; the state NAME is that key.
  const getStateSnapshot = React.useCallback(() => rt.state as DialogState, [rt]);
  const state = React.useSyncExternalStore(subscribe, getStateSnapshot, getStateSnapshot);

  const ctx = rt.context as Required<DialogConfig> & Record<string, unknown>;
  const isOpen = state === "open";

  const open = React.useCallback(() => rt.send("OPEN"), [rt]);
  const close = React.useCallback(() => rt.send("CLOSE"), [rt]);

  // The dialog surface element — populated when the consumer spreads getContentProps().
  const contentRef = React.useRef<HTMLElement>(null);

  // Realise the machine's declarative DOM concerns (focus trap + ESC + scroll lock).
  // Core dialogs are always modal (aria-modal="true"), so lock scroll while open.
  useDialogDom(contentRef, isOpen, close, { modal: true });

  const resizable = dialogMachine.guards.canResize(ctx); // pure guard from the core machine

  return {
    state,
    isOpen,
    open,
    close,
    contentRef,

    getOverlayProps: () =>
      normalizeProps({
        part: "overlay",
        "data-state": state,
        // Click-on-backdrop dismiss is a connector concern (parts.md), not styling.
        onClick: () => close(),
      }),

    getContentProps: () =>
      normalizeProps({
        // Expose the surface element so useDialogDom can query/cycle focusables.
        ref: contentRef,
        part: "content",
        role: "dialog",
        "aria-modal": "true",
        "aria-labelledby": titleId,
        "data-state": state,
        // resizable + dimensions — inline style ONLY when the instance opted in (canResize).
        // overflow:hidden (NOT auto) keeps the resize grip working while leaving scrolling
        // to [part="body"]'s data-scroll rule — so resizing no longer forces a scrollbar in
        // the no-scroll config (round-4 defect 2, cause #2). The surface still CLIPS; the
        // inner body owns overflow.
        style: resizable
          ? {
              resize: "both",
              overflow: "hidden",
              width: ctx.width ?? undefined,
              height: ctx.height ?? undefined,
            }
          : undefined,
        // Stop backdrop click from bubbling and closing when interacting with content.
        onClick: (e: React.MouseEvent) => e.stopPropagation(),
      }),

    // The body part — the single scroll region. Thin connector: just reflect the
    // machine's scrollable context to a data-attribute; core/design/dialog.css turns
    // it into overflow:auto (scroll) vs overflow:hidden (no-scroll) on [part="body"].
    getBodyProps: () =>
      normalizeProps({
        part: "body",
        "data-scroll": ctx.scrollable ? "scroll" : "no-scroll",
      }),

    getTitleProps: () =>
      normalizeProps({
        part: "title",
        id: titleId,
      }),

    getCloseProps: () =>
      normalizeProps({
        part: "close",
        type: "button",
        "aria-label": "Close dialog",
        onClick: () => close(),
      }),
  };
}

export default useDialog;

designHooks.content:
/* custom/design/dialog.css
 * The CUSTOM (custom/company) brand design layer for the dialog (behavior-layer-design.md §3.2 / §5.2,
 * separation-architecture.md §3).
 *
 * Layered AFTER core/design/dialog.css (the resolver returns css = [ core, custom ] in that
 * order — §4.2, and App.tsx imports core first then custom). It is purely ADDITIVE brand
 * chrome: it styles the custom-only `brandHeader` part, the custom-only window-control
 * parts (`minimize` / `restore`), the brand accent on the core `close` part, and the
 * custom-only `minimized` data-state — all via the SAME parts.md/parts.extend.md contract
 * selectors. It never edits the core CSS file and never imports a behavior/machine file.
 *
 * THEME-SCOPED BRANDING (separation-architecture.md §3, fixes d7 defect b): the brand colors
 * are NO LONGER raw literals in this file. They are THEME tokens (--brand-header-bg,
 * --brand-header-fg, --brand-control-*, --brand-logo, --brand-on) supplied by the active
 * theme's token bundle (tokens/themes/<dir>/brand.json -> dist/themes/<dir>/variables.css).
 * The custom/company theme FILLS them (BLUE header, YELLOW/RED controls, logo); the core
 * themes (default/midnight) leave them OFF (transparent header, currentColor ink, no logo).
 * So this stylesheet stays TOKEN-ONLY on [part]/[data-state] with NO raw hex, and the brand
 * chrome renders ONLY when a branded theme fills the capability — it cannot leak into a core
 * theme, because under a core theme --brand-header-bg etc. are transparent/neutral.
 */

/* ── Brand header: the custom-only part, layered on top of [part="content"] ──── */
[part="brandHeader"] {
  /* Own positioning context so the brand window-controls anchor to the HEADER bar
   * (core makes [part=content] position:relative; we don't want them to escape to the
   * content corner). Additive — the core file is untouched. */
  position: relative;
  /* ROUND-4 STICKY HEADER (defect 3): the brand header is the custom dialog's header
   * zone. Core makes [part=content] a flex column whose only scroll region is
   * [part=body]; flex:0 0 auto pins this bar as a non-shrinking row OUTSIDE that scroll
   * region, so it stays put while the body scrolls. Additive — no core edit. */
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: var(--space-3);
  /* BLUE brand header under a branded theme; TRANSPARENT (plain) under core themes —
   * the value is the theme token, never a literal. */
  background: var(--brand-header-bg);
  color: var(--brand-header-fg);
  padding: var(--space-3) var(--space-6);
  /* sit flush with the rounded top of the core content surface */
  border-top-left-radius: var(--radius-lg);
  border-top-right-radius: var(--radius-lg);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
  /* pull out to the content padding edges so the bar spans the surface */
  margin: calc(-1 * var(--space-6)) calc(-1 * var(--space-6)) var(--space-6);
}

[part="brandHeader"]:hover {
  background: var(--brand-header-bg-strong);
}

[part="brandHeader"] .company-dialog__brand {
  letter-spacing: 0.04em;
  opacity: 0.95;
}

/* The brand title sits on the brand bar, so it inherits the brand header ink. */
[part="brandHeader"] [part="title"] {
  color: var(--brand-header-fg);
}

/* ── Shared geometry for the brand window controls (minimize / restore / close) ──── */
[part="brandHeader"] [part="minimize"],
[part="brandHeader"] [part="restore"],
[part="brandHeader"] [part="close"] {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  border: none;
  cursor: pointer;
  font: inherit;
  font-weight: var(--font-weight-semibold);
  line-height: 1;
  /* geometry is core-token-shaped (not brand-specific), inlined now the brand :root block is gone */
  padding: var(--space-1, 4px) var(--space-3, 12px);
  border-radius: var(--radius-md, 6px);
}

/* ── YELLOW: minimize + restore (defect 2 affordance + defect 3 brand color) ──── */
/* These two controls live in the brand header, which is the only part the minimized
 * data-state keeps visible — so the restore control is always reachable. */
[part="brandHeader"] [part="minimize"],
[part="brandHeader"] [part="restore"] {
  background: var(--brand-control-yellow);
  color: var(--brand-control-on-yellow);
}

[part="brandHeader"] [part="minimize"]:hover,
[part="brandHeader"] [part="restore"]:hover {
  background: var(--brand-control-yellow-strong);
}

[part="brandHeader"] [part="minimize"]:focus-visible,
[part="brandHeader"] [part="restore"]:focus-visible {
  outline: 2px solid var(--brand-header-fg);
  outline-offset: 2px;
}

/* ── RED: the close affordance (brand accent over the core [part="close"]) ──── */
/* Core styles [part="close"] as a transparent ghost button; the custom layer (loaded
 * AFTER core) overrides it to the brand RED inside the brand header. No core edit. */
[part="brandHeader"] [part="close"] {
  position: static; /* override the core absolute top/right anchoring inside the bar */
  background: var(--brand-control-red);
  color: var(--brand-control-on-red);
}

[part="brandHeader"] [part="close"]:hover {
  background: var(--brand-control-red-strong);
  color: var(--brand-control-on-red);
}

[part="brandHeader"] [part="close"]:focus-visible {
  outline: 2px solid var(--brand-header-fg);
  outline-offset: 2px;
}

/* ── Minimized: the custom-only data-state (collapse to just the brand header) ── */
/* Show ONLY the brand header chrome; hide the body until RESTORE. Because the
 * window controls now live in the header, the YELLOW restore + RED close stay
 * visible while minimized (the fix for "stuck minimized" — defect 2).
 *
 * ROUND-4 THEME-CONSISTENT MINIMIZE (defect 1): the docked chrome must look the SAME
 * in light AND dark — only its color may differ with the theme. The round-3 bug was
 * that the collapsed dock still wore the CORE neutral surface skin
 * (core: [part=content] background:surface.raised + border:border.default). Under
 * midnight those two tokens COLLAPSE to the same gray (surface.raised == border.default
 * == gray.700) on a gray.900 page, so the frame edge vanished and the dock read as a
 * "bare bar / empty body" — while in light it was a crisp card frame. The structure was
 * theme-DEPENDENT.
 *
 * Fix: when minimized, the dock IS the brand header alone. We additively override the
 * core surface to transparent/borderless (custom layer loads after core — no core
 * edit) so the only visible chrome is the brand bar, whose color is the theme's brand
 * token (under the company theme the BLUE --brand-header-bg is identical in both core
 * themes by design). The float shadow uses the same theme-stable dark token as the
 * overlay scrim. Result: the minimized dialog is STRUCTURALLY IDENTICAL across themes —
 * a single rounded brand bar — and only the brand color paints it, so light and dark match. */
[part="content"][data-state="minimized"] {
  overflow: hidden;
  max-height: none;
  /* shed the core neutral surface frame that diverged across themes */
  padding: 0;
  background: transparent;
  border-color: transparent;
  /* keep the dock floating with a theme-stable (dark) shadow, like the scrim */
  box-shadow: 0 8px 24px color-mix(in srgb, var(--color-primitive-gray-900) 40%, transparent);
}

[part="content"][data-state="minimized"] > :not([part="brandHeader"]) {
  display: none;
}

/* The collapsed bar becomes a self-contained, fully-rounded brand card: drop the
 * break-out negative margins (no surface to break out of now) and round all four
 * corners so the dock looks identical in both themes. */
[part="content"][data-state="minimized"] [part="brandHeader"] {
  margin: 0;
  border-radius: var(--radius-lg);
}
